      const localCache = new Map<string, Promise<import("@reqflow/core").CollectedItem[]>>();
      const cachedDocuments = {
        ...documents,
        read(id: string, maxPages: number, signal: AbortSignal) {
          const key = `${id}:${maxPages}`;
          let result = localCache.get(key);
          if (!result) {
